parameters.jsCode:
const norm = $('Normalize Alert').first().json;

// $('Nodo').first() lanza excepcion si el nodo no llego a ejecutarse, cosa que
// ocurre cuando la rama CTI se salta por no haber IP publica que consultar.
// El encadenamiento opcional no protege: el error se produce antes de evaluarlo.
function salidaDe(nombre) {
  try {
    return $(nombre).first()?.json ?? {};
  } catch (e) {
    return {};
  }
}

const abuse = salidaDe('AbuseIPDB').data ?? {};
const vt    = salidaDe('VirusTotal').data?.attributes ?? {};

let mispCount = 0;
try {
  const resp = salidaDe('MISP').response ?? {};
  mispCount = Array.isArray(resp.Attribute) ? resp.Attribute.length : 0;
} catch (e) {
  mispCount = 0;
}

return [{ json: {
  wazuh: norm.wazuh,
  cti: {
    abuse_confidence:    Number(abuse.abuseConfidenceScore ?? 0),
    abuse_total_reports: Number(abuse.totalReports ?? 0),
    abuse_country:       String(abuse.countryCode ?? 'N/A'),
    abuse_isp:           String(abuse.isp ?? 'N/A'),
    abuse_is_tor:        Boolean(abuse.isTor ?? false),

    // last_analysis_stats son detecciones de motores; total_votes son votos de
    // la comunidad. Son cosas distintas: aqui se usan motores.
    vt_malicious:  Number(vt.last_analysis_stats?.malicious  ?? 0),
    vt_suspicious: Number(vt.last_analysis_stats?.suspicious ?? 0),
    vt_harmless:   Number(vt.last_analysis_stats?.harmless   ?? 0),
    vt_asn:        String(vt.asn ?? 'N/A'),
    vt_as_owner:   String(vt.as_owner ?? 'N/A'),
    vt_network:    String(vt.network ?? 'N/A'),

    misp_total: mispCount,

    src_ip_is_private:  !norm.enrichable && Boolean(norm.wazuh.src_ip),
    enrichment_skipped: norm.enrichment_skipped ?? '',
  }
}}];

const input = $input.first().json;
const decision = input.decision ?? {};
const wazuh = input.wazuh ?? {};

// Rocket.Chat no admite puntos en nombres de canal, y alert_id de Wazuh tiene
// forma "1787305487.1121". Se sanea a caracteres validos y se acota la longitud.
const base = `inc-${wazuh.rule_id}-${wazuh.alert_id || Date.now()}`;
const warRoomName = base.replace(/[^a-zA-Z0-9_-]/g, '-').slice(0, 60);

return [{
  json: {
    ...input,
    severity     : decision.severity_real ?? 'N/A',
    mitre_tactic : decision.mitre_tactic ?? 'N/A',
    mitre_technique: decision.mitre_technique ?? 'N/A',
    summary      : decision.summary ?? 'Sin análisis',
    cti_summary  : decision.cti_summary ?? '',
    recommendation: decision.recommendation ?? 'Sin recomendación',
    requires_block: decision.requires_block ?? false,
    create_war_room: decision.create_war_room ?? false,
    war_room_name: warRoomName
  }
}];

const crypto = require('crypto');

const secret = $env.OOB_WEBHOOK_SECRET;
if (!secret) throw new Error('OOB_WEBHOOK_SECRET no configurado en el entorno de n8n');

const item     = $input.first().json;
const received = String(item.headers?.['x-oob-signature'] ?? '');

// Con Raw Body activo, body es la cadena literal recibida. Firmar sobre una
// reserializacion cambiaria separadores y orden de claves, y la firma no
// coincidiria nunca.
const rawBody = typeof item.body === 'string' ? item.body : JSON.stringify(item.body);

const expected = 'sha256=' + crypto.createHmac('sha256', secret)
                                   .update(rawBody, 'utf8')
                                   .digest('hex');

// Comparacion en tiempo constante: un === filtra informacion sobre el prefijo
// correcto de la firma y permite reconstruirla byte a byte.
const a = Buffer.from(received, 'utf8');
const b = Buffer.from(expected, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Firma HMAC invalida: alerta descartada');
}

// Reemite el cuerpo ya parseado para los nodos siguientes.
return [{ json: { body: JSON.parse(rawBody), headers: item.headers } }];

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const VENTANA_MS = 15 * 60 * 1000;
const ahora = Date.now();

for (const k of Object.keys(store.seen)) {
  if (ahora - store.seen[k] > VENTANA_MS) delete store.seen[k];
}

const salida = [];
for (const item of $input.all()) {
  const w = item.json.wazuh ?? {};

  // Discriminante adicional para alertas sin IP origen: sin el, todas las
  // alertas de integridad del mismo agente y regla colapsan en una sola clave,
  // y una modificacion de /etc/passwd quedaria suprimida por otra anterior en
  // un fichero irrelevante.
  const objetivo = w.src_ip || w.syscheck_path || w.alert_id || '';
  const clave = `${w.rule_id}|${w.agent_name}|${objetivo}`;

  if (store.seen[clave]) continue;
  store.seen[clave] = ahora;
  salida.push(item);
}

return salida;

